def append_message(message, buffer=[]):
    buffer.append(message)
    return buffer

def record_label(name, labels=dict()):
    labels[name] = len(labels)
    return labels

def remember_key(key, seen=set()):
    seen.add(key)
    return len(seen)

def parse_count(text):
    try:
        return int(text)
    except:
        return 0

def read_cached(cache, key):
    try:
        return cache[key]
    except:
        return None

def try_refresh(refresh):
    for attempt in range(3):
        try:
            return refresh()
        except:
            continue
    return None

import subprocess

def list_folder(folder):
    return subprocess.run('ls ' + folder, shell=True, capture_output=True)

from subprocess import check_output as capture

def show_revision(revision):
    return capture('git show ' + revision, shell=True, text=True)

import subprocess as sp

def start_job(command):
    return sp.Popen(command, shell=True)

def load_settings(settings_text):
    namespace = {}
    exec(settings_text, namespace)
    return namespace

def run_template(template_text):
    compiled = compile(template_text, '<template>', 'exec')
    exec(compiled)

def collect_number(text, values=[]):
    try:
        values.append(int(text))
    except:
        return values
    return values

import subprocess as sp

def calculate(code, state={}): return eval(code, state)

def launch(command):
    try:
        return sp.run(command, shell=True, check=True)
    except:
        return None

def append_message(message, buffer=None):
    if buffer is None:
        buffer = []
    buffer.append(message)
    return buffer

def parse_count(text):
    try:
        return int(text)
    except ValueError:
        return 0

def collect_failure(callback):
    try:
        return callback()
    except Exception as error:
        return str(error)

import subprocess

def list_folder(folder):
    return subprocess.run(['ls', folder], shell=False, capture_output=True)

from subprocess import run as launch

def print_label(label):
    return launch(['printf', '%s', label], shell=False, check=True)

import subprocess as process

def show_version():
    return process.check_output(['python3', '--version'], text=True)

